    Bug 2052910 - Account Hub: Don't populate host or user name when coming from protocol select. r=klamping

    TB-Tools-Id: c29878b0-fb5c-4556-bf19-22aadd0f5cac

    Differential Revision: https://phabricator.services.mozilla.com/D312415

diff --git a/mail/components/accountcreation/views/email.mjs b/mail/components/accountcreation/views/email.mjs
index fab649df60d..1e8392b56d5 100644
--- a/mail/components/accountcreation/views/email.mjs
+++ b/mail/components/accountcreation/views/email.mjs
@@ -818,10 +818,9 @@ class AccountHubEmail extends HTMLElement {
           newManualConfigPref &&
           this.#currentState == "emailConfigFoundSubview"
         ) {
-          this.#initManualConfig(
-            this.#currentConfig.incoming.type,
-            "emailConfigFoundSubview"
-          );
+          this.#initManualConfig(this.#currentConfig.incoming.type, {
+            previousStep: "emailConfigFoundSubview",
+          });
           break;
         }

@@ -1178,7 +1177,9 @@ class AccountHubEmail extends HTMLElement {
         break;
       case "protocolSelectSubview":
         this.#currentConfig.incoming.type = stateData.protocolSelect;
-        await this.#initManualConfig(stateData.protocolSelect);
+        await this.#initManualConfig(stateData.protocolSelect, {
+          clearHostnames: true,
+        });
         break;
       case "manualConfigSubview":
         if (!(await this.#currentSubview.validate())) {
@@ -1443,9 +1444,16 @@ class AccountHubEmail extends HTMLElement {
    * Initialize the correct manual config step based on the protocol.
    *
    * @param {string} protocol - The selected incoming protocol.
-   * @param {string} previousStep - The step the protocol form goes back to.
-   */
-  async #initManualConfig(protocol, previousStep = "protocolSelectSubview") {
+   * @param {object} [options]
+   * @param {string} [options.previousStep="protocolSelectSubview"] - The step
+   *   the protocol form goes back to.
+   * @param {boolean} [options.clearHostnames=false] - Whether hostname fields
+   *   should be empty when showing the manual config form.
+   */
+  async #initManualConfig(
+    protocol,
+    { previousStep = "protocolSelectSubview", clearHostnames = false } = {}
+  ) {
     switch (protocol) {
       case "imap":
       case "pop3":
@@ -1459,7 +1467,12 @@ class AccountHubEmail extends HTMLElement {
     }

     this.#states[this.#currentState].previousStep = previousStep;
-    this.#setCurrentConfigForSubview();
+    const config = this.#currentConfig.copy();
+    if (clearHostnames && ["imap", "pop3"].includes(protocol)) {
+      config.incoming.hostname = "";
+      config.outgoing.hostname = "";
+    }
+    this.#currentSubview.setState(config);
   }

   /**
diff --git a/mail/test/browser/account/browser_accountHubManualConfig.js b/mail/test/browser/account/browser_accountHubManualConfig.js
index de261f4599a..a7aa2bad82f 100644
--- a/mail/test/browser/account/browser_accountHubManualConfig.js
+++ b/mail/test/browser/account/browser_accountHubManualConfig.js
@@ -1243,6 +1243,31 @@ add_task(async function test_direct_to_manual_config_pref_enabled() {
     "The direct manual config flow should default to IMAP"
   );

+  await subtest_select_protocol_and_continue(dialog, "imap");
+
+  const manualConfigTemplate = dialog.querySelector(
+    "#emailManualConfigSubview"
+  );
+  await BrowserTestUtils.waitForAttributeRemoval(
+    "hidden",
+    manualConfigTemplate
+  );
+  Assert.equal(
+    manualConfigTemplate.captureState().incoming.type,
+    "imap",
+    "The manual config form should use the selected IMAP protocol"
+  );
+  subtest_assert_manual_config_hostnames_empty(manualConfigTemplate, "IMAP");
+
+  EventUtils.synthesizeMouseAtCenter(
+    dialog.querySelector("#emailFooter #back"),
+    {}
+  );
+  await BrowserTestUtils.waitForAttributeRemoval(
+    "hidden",
+    protocolSelectTemplate
+  );
+
   await subtest_select_protocol_and_continue(dialog, "microsoft");

   const exchangeSettingsSubview = dialog.querySelector(
@@ -1281,9 +1306,6 @@ add_task(async function test_direct_to_manual_config_pref_enabled() {

   await subtest_select_protocol_and_continue(dialog, "pop3");

-  const manualConfigTemplate = dialog.querySelector(
-    "#emailManualConfigSubview"
-  );
   await BrowserTestUtils.waitForAttributeRemoval(
     "hidden",
     manualConfigTemplate
@@ -1297,6 +1319,7 @@ add_task(async function test_direct_to_manual_config_pref_enabled() {
     "pop3",
     "The manual config form should use the selected POP3 protocol"
   );
+  subtest_assert_manual_config_hostnames_empty(manualConfigTemplate, "POP3");

   await subtest_close_account_hub_dialog(dialog, manualConfigTemplate);
   await cleanupManualConfigPref();
@@ -1911,3 +1934,19 @@ function subtest_assert_protocol_select_chrome(dialog, protocolSelectTemplate) {
     "The protocol select screen should show the notification bar"
   );
 }
+
+function subtest_assert_manual_config_hostnames_empty(
+  manualConfigTemplate,
+  protocol
+) {
+  Assert.equal(
+    manualConfigTemplate.querySelector("#manualIncomingHostname").value,
+    "",
+    `${protocol} manual config should not populate the incoming hostname`
+  );
+  Assert.equal(
+    manualConfigTemplate.querySelector("#manualOutgoingHostname").value,
+    "",
+    `${protocol} manual config should not populate the outgoing hostname`
+  );
+}
